
import React, { useEffect, useState, useRef } from "react";
import { getStore, gen16CodeId, ObjectKeys, getLabelTranslate, fetchEncryptStream, qryKprofile, qryStore, txtOrempty,
	} from "../../../stores/Utils";

import {DropInput_Cmpt } from "../../../components";
import "./styles.css"
import { getall_product } from "../services/server_fetching";


const DropInput = DropInput_Cmpt();


const collName = "products_list"



const SelectProducts  = ({ handleClick, exFlds }) => {

	
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [loading, set_loading] = useState(false);
	const [list, setList] = useState([]);

	const searchRef = useRef();

	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			set_obs(gen16CodeId())
		}
    });


    const cb_result =  (v) => {
		set_obs(gen16CodeId())
	}

	const handleChange =  (v) => {
		!loading && set_loading(true)
	}

	const handle_3earch =  (a,v) => {
		setList(filterArr(a,v))
		loading && set_loading(false)
	}





	const parseD =  (v) => {
		let nA = []
		v && ObjectKeys(v).map(cl=>{
			let fullNm = txtOrempty(v[cl]?.firstName) + txtOrempty(v[cl]?.middleName)  + txtOrempty(v[cl]?.lastName);
			nA.push({id:cl, label: fullNm, data: v[cl] });
		})
		setList(nA);
	}

	const handle_search = async (v) => {
		let dt = await search_notary_cl(v, exFlds);
	
		setList(dt);
		loading && set_loading(false)
	}

	const handle_empty =  (v) => {
		setList([]);
		loading && set_loading(false)
	}
	
	
    
    const selectItem =  (acc,subacc) => {
		handleClick(acc,subacc);
		searchRef.current.clearTx();
	}

	

    return (
		<div>
			<DropInput
				placeholder={getLabelTranslate(12)} 
				width={420}
				fetchData={handle_search}
				loading={loading}
				change={handleChange}
				callempty={handle_empty}
				ref={searchRef}
			>
				<div className="">
					{list && ObjectKeys(list)?.map(cid=>{
						return (
							<Item 
								data={list[cid]}
								elmId={cid} 
								key={cid}
								selectItem={selectItem}
							/>
						)
					})}
				</div>
			</DropInput>
		</div>
    )   
}

export default SelectProducts;




const Item  = ({ data,  selectItem }) => {
	
	return (
		<div className="item_acc">
			<div className="_dsplFlx item_box account_header">
				<div className="_dsplFlx"  onClick={()=>selectItem(data, null)}>
					<div className="code" >
						{data?.name} 
					</div>
				</div>
			</div>
			
		</div>
	)
}



function filterArr(arr1,search) {
	let srch = search.toLowerCase();
    var newArr = [];
    if (arr1.length > 0) {
		arr1.map((s) => {
			if (s["name"]?.toLowerCase()?.indexOf(srch)>=0 || s["upc_barcode"]?.toString()?.toLowerCase()?.indexOf(srch)>=0 ) {
				newArr.push(s);
			}
		})
	}
	return newArr;
}






const search_notary_cl = async (search,extraFields ) => {
    if(search.length>2){
       
		let bdyq2 = {...getStore(qryStore())?.search_prod};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			limit: 120,
			year: getStore("date_current_year")
		}
		bdyq2.extraFields = extraFields;


        search.split(" ").map((qry,inDq)=>{
            if(qry){
                bdyq2.params[":search"+inDq] = qry.trim();
            }
        });
       
        bdyq2.params[":search5"] = getStore(qryKprofile())?.businessId;
        
        const res = fetchEncryptStream(bdyq2);
        const td = await res;
        if (td && !td.error) {
            return td
        }
    }
   
    return null;
    
};